files.content:
.progress{
  display:flex;
  align-items:center;
  gap:var(--s-4);
}
.progress-label{
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  text-transform:uppercase;
  color:var(--obsidian-300);
}
.progress-track{
  flex:1;
  height:var(--s-2);
  border-radius:var(--r-full);
  background:var(--obsidian-700);
}
.progress-sm .progress-track{
  height:var(--s-1);
}
.progress-fill{
  height:100%;
  width:var(--value, 0%);
  border-radius:inherit;
  background:var(--grad-progress);
  box-shadow:var(--sh-glow-soft);
  transform-origin:left;
  transition:width var(--d-scene) var(--ease-decel);
}
.progress-value{
  font-size:var(--t-small);
  color:var(--obsidian-100);
  font-variant-numeric:tabular-nums;
}
.progress[data-reveal] .progress-fill{
  transform:scaleX(0);
}
@media (prefers-reduced-motion: reduce){
  .progress-fill{
    transition:none;
  }
  .progress[data-reveal] .progress-fill{
    transform:none;
    transition:none;
  }
}
.progress{
  width:min(100%, calc(var(--s-32) * 2));
}
